"use strict";const DEFAULT_PASSWORD_LENGTH=32,ALL_CHARS="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz123456789",MIN_GENERATED_LENGTH=12;function generatePassword(t,o,d){const n=document.getElementById(o),e=document.getElementById(d),s=window.crypto||window.msCrypto;if(!n||!e||!s||typeof s.getRandomValues!="function")return"";let r=Number.parseInt(t,10);(!Number.isFinite(r)||r<12)&&(r=32);const c=[];for(;c.length<r;)c.push(randomCharacter(ALL_CHARS));const i=c.join("");n.type="text",n.value=i,e.type="text",e.value=i;const a=window.navigator&&window.navigator.clipboard;return a&&typeof a.writeText=="function"&&a.writeText(i).catch(()=>{}),n.focus(),n.select(),document.execCommand("copy"),i}function randomCharacter(t){return t[cryptoRandomInt(t.length)]}function cryptoRandomInt(t){if(t<=0)return 0;const o=window.crypto||window.msCrypto;if(!o||typeof o.getRandomValues!="function")throw new Error("Secure random generator unavailable");const n=Math.floor(4294967296/t)*t,e=new Uint32Array(1);do o.getRandomValues(e);while(e[0]>=n);return e[0]%t}
